class Solution:
    def lexSmallest(self, s: str) -> str:
        n = len(s)
        best = s
        for k in range(1, n + 1):
            c = s[:k][::-1] + s[k:]
            if c < best:
                best = c
            c = s[:n - k] + s[n - k:][::-1]
            if c < best:
                best = c
        return best

