class Solution {
public:
    string lexSmallest(string s) {
        int n = s.size();
        string best = s;
        for (int k = 1; k <= n; k++) {
            string c = s.substr(0, k);
            reverse(c.begin(), c.end());
            c += s.substr(k);
            best = min(best, c);
            c = s.substr(0, n - k);
            string t = s.substr(n - k);
            reverse(t.begin(), t.end());
            c += t;
            best = min(best, c);
        }
        return best;
    }
};

