        int n = s.length();
        String best = s;
        for (int k = 1; k <= n; k++) {
            StringBuilder sb = new StringBuilder(s.substring(0, k)).reverse();
            sb.append(s.substring(k));
            if (sb.toString().compareTo(best) < 0) best = sb.toString();
            sb = new StringBuilder(s.substring(n - k)).reverse();
            sb.insert(0, s.substring(0, n - k));
            if (sb.toString().compareTo(best) < 0) best = sb.toString();
        }
        return best;
    }
}

