class Solution:
    def lexSmallest(self, s: str) -> str:
        MOD = (1 << 61) - 1
        B = 131
        n = len(s)
        rv = s[::-1]
        hs = [0] * (n + 1); hr = [0] * (n + 1); pw = [1] * (n + 1)
        for i in range(n):
            hs[i + 1] = (hs[i] * B + ord(s[i])) % MOD
            hr[i + 1] = (hr[i] * B + ord(rv[i])) % MOD
            pw[i + 1] = pw[i] * B % MOD
        def H(arr, l, r):
            return (arr[r] - arr[l] * pw[r - l]) % MOD
        def pieces(t, x):
            if t == 'p':
                return [(hr, n - x, x), (hs, x, n - x)]
            return [(hs, 0, x), (hr, 0, n - x)]
        def chash(ps, l, r):
            res = 0; cur = 0
            for arr, off, ln in ps:
                lo, hi = max(l, cur), min(r, cur + ln)
                if lo < hi:
                    res = (res * pw[hi - lo] + H(arr, off + lo - cur, off + hi - cur)) % MOD
                cur += ln
            return res
        def better(a, b):
            la, lb = len(a[2]), len(b[2])
            lo, hi = 0, min(la, lb)
            while lo < hi:
                mid = (lo + hi + 1) // 2
                if chash(a[2], 0, mid) == chash(b[2], 0, mid):
                    lo = mid
                else:
                    hi = mid - 1
            ca = chash(a[2], lo, lo + 1) if lo < la else -1
            cb = chash(b[2], lo, lo + 1) if lo < lb else -1
            return ca < cb
        best = None
        for k in range(1, n + 1):
            for c in (('p', k, pieces('p', k)), ('s', n - k, pieces('s', n - k))):
                if best is None or better(c, best):
                    best = c
        return ''.join((rv if arr is hr else s)[off:off + ln] for arr, off, ln in best[2])

