using ull = unsigned long long;
const ull MOD = (1ULL << 61) - 1;
ull mulmod(ull a, ull b) {
    __int128 c = (__int128)a * b;
    ull m = (ull)(c & MOD) + (ull)(c >> 61);
    return m >= MOD ? m - MOD : m;
}
class Solution {
public:
    struct Cand { bool pre; int x; };
    string lexSmallest(string s) {
        int n = s.size();
        string rv(s.rbegin(), s.rend());
        vector<ull> hs(n + 1, 0), hr(n + 1, 0), pw(n + 1, 1);
        for (int i = 0; i < n; i++) {
            hs[i + 1] = (mulmod(hs[i], 131) + s[i]) % MOD;
            hr[i + 1] = (mulmod(hr[i], 131) + rv[i]) % MOD;
            pw[i + 1] = mulmod(pw[i], 131);
        }
        auto H = [&](vector<ull>& a, int l, int r) {
            return (a[r] + MOD - mulmod(a[l], pw[r - l])) % MOD;
        };
        auto chash = [&](bool pre, int x, int l, int r) {
            ull res = 0; int cur = 0;
            auto add = [&](vector<ull>& a, int off, int ln) {
                int lo = max(l, cur), hi = min(r, cur + ln);
                if (lo < hi) {
                    res = (mulmod(res, pw[hi - lo]) + H(a, off + lo - cur, off + hi - cur)) % MOD;
                }
                cur += ln;
            };
            if (pre) { add(hr, n - x, x); add(hs, x, n - x); }
            else { add(hs, 0, x); add(hr, 0, n - x); }
            return res;
        };
        auto better = [&](bool pa, int xa, bool pb, int xb) {
            int lo = 0, hi = n;
            while (lo < hi) {
                int mid = (lo + hi + 1) / 2;
                if (chash(pa, xa, 0, mid) == chash(pb, xb, 0, mid)) lo = mid;
                else hi = mid - 1;
            }
            ull ca = lo < n ? chash(pa, xa, lo, lo + 1) : 0;
            ull cb = lo < n ? chash(pb, xb, lo, lo + 1) : 0;
            if (ca != cb) return ca < cb;
            return false;
        };
        bool bp = true; int bx = 1;
        for (int k = 1; k <= n; k++) {
            if (better(true, k, bp, bx)) { bp = true; bx = k; }
            if (better(false, n - k, bp, bx)) { bp = false; bx = n - k; }
        }
        if (bp) {
            string res = string(rv.rbegin() + (n - bx), rv.rend());
            res += s.substr(bx);
            return res;
        }
        string res = s.substr(0, bx);
        res += string(rv.rbegin(), rv.rend() - bx);
        return res;
    }
};

