class Solution {
    static final long MOD = 2147483647L;
    public String lexSmallest(String s) {
        int n = s.length();
        String rv = new StringBuilder(s).reverse().toString();
        long[] hs = new long[n + 1], hr = new long[n + 1], pw = new long[n + 1];
        pw[0] = 1;
        for (int i = 0; i < n; i++) {
            hs[i + 1] = (hs[i] * 131 + s.charAt(i)) % MOD;
            hr[i + 1] = (hr[i] * 131 + rv.charAt(i)) % MOD;
            pw[i + 1] = pw[i] * 131 % MOD;
        }
        long[] bestH = null;
        boolean bestPre = true; int bestX = 1;
        for (int k = 1; k <= n; k++) {
            if (cmp(true, k, bestPre, bestX, hs, hr, pw, n)) { bestPre = true; bestX = k; }
            if (cmp(false, n - k, bestPre, bestX, hs, hr, pw, n)) { bestPre = false; bestX = n - k; }
        }
        StringBuilder sb = new StringBuilder();
        if (bestPre) {
            sb.append(new StringBuilder(s.substring(0, bestX)).reverse());
            sb.append(s.substring(bestX));
        } else {
            sb.append(s.substring(0, bestX));
            sb.append(new StringBuilder(s.substring(bestX)).reverse());
        }
        return sb.toString();
    }
    private long seg(boolean pre, int x, int l, int r, long[] hs, long[] hr, long[] pw, int n) {
        long res = 0; int cur = 0;
        long[][] src = pre ? new long[][]{hr, hs} : new long[][]{hs, hr};
        int[] offs = pre ? new int[]{n - x, x} : new int[]{0, 0};
        int[] lens = pre ? new int[]{x, n - x} : new int[]{x, n - x};
        for (int p = 0; p < 2; p++) {
            int lo = Math.max(l, cur), hi = Math.min(r, cur + lens[p]);
            if (lo < hi) {
                long[] a = src[p]; int off = offs[p];
                long h = (a[off + hi - cur] + MOD - a[off + lo - cur] * pw[hi - lo] % MOD) % MOD;
                res = (res * pw[hi - lo] + h) % MOD;
            }
            cur += lens[p];
        }
        return res;
    }
    private boolean cmp(boolean pa, int xa, boolean pb, int xb, long[] hs, long[] hr, long[] pw, int n) {
        int lo = 0, hi = n;
        while (lo < hi) {
            int mid = (lo + hi + 1) / 2;
            if (seg(pa, xa, 0, mid, hs, hr, pw, n) == seg(pb, xb, 0, mid, hs, hr, pw, n)) lo = mid;
            else hi = mid - 1;
        }
        long ca = lo < n ? seg(pa, xa, lo, lo + 1, hs, hr, pw, n) : -1;
        long cb = lo < n ? seg(pb, xb, lo, lo + 1, hs, hr, pw, n) : -1;
        return ca < cb;
    }
}

