    for (let i = 0; i < n; i++) {
        hs[i + 1] = (hs[i] * B + BigInt(s.charCodeAt(i))) % MOD;
        hr[i + 1] = (hr[i] * B + BigInt(rv.charCodeAt(i))) % MOD;
        pw[i + 1] = pw[i] * B % MOD;
    }
    const seg = (pre, x, l, r) => {
        let res = 0n, cur = 0;
        const parts = pre ? [[hr, n - x, x], [hs, x, n - x]] : [[hs, 0, x], [hr, 0, n - x]];
        for (const [a, off, ln] of parts) {
            const lo = Math.max(l, cur), hi = Math.min(r, cur + ln);
            if (lo < hi) {
                const h = (a[off + hi - cur] + MOD - a[off + lo - cur] * pw[hi - lo] % MOD) % MOD;
                res = (res * pw[hi - lo] + h) % MOD;
            }
            cur += ln;
        }
        return res;
    };
    const cmp = (pa, xa, pb, xb) => {
        let lo = 0, hi = n;
        while (lo < hi) {
            const mid = (lo + hi + 1) >> 1;
            if (seg(pa, xa, 0, mid) === seg(pb, xb, 0, mid)) lo = mid; else hi = mid - 1;
        }
        const ca = lo < n ? seg(pa, xa, lo, lo + 1) : -1n;
        const cb = lo < n ? seg(pb, xb, lo, lo + 1) : -1n;
        return ca < cb;
    };
    let bp = true, bx = 1;
    for (let k = 1; k <= n; k++) {
