        if (cmp(false, n - k, bp, bx)) { bp = false; bx = n - k; }
    }
    if (bp) return s.slice(0, bx).split('').reverse().join('') + s.slice(bx);
    return s.slice(0, bx) + s.slice(bx).split('').reverse().join('');
